// Helper function to count positive integers
function CountPositive(l: seq<int>): int
    requires l != null
    ensures CountPositive(l) >= 0
{
    if |l| == 0 then
        return 0;
    else
        var count := CountPositive(tail(l));
        if head(l) > 0 then
            return count + 1;
        else
            return count;
}

